def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    mr = hypot(me.x, me.y)
    er = hypot(enemy.x, enemy.y)
    dx = me.x - enemy.x
    dy = me.y - enemy.y
    de = hypot(dx, dy)

    if mr > 5.0:
        tx = 0.0
        ty = 0.0
    elif de < 0.1:
        tx = enemy.x
        ty = enemy.y
    else:
        tx = enemy.x + dx / de * 1.0
        ty = enemy.y + dy / de * 1.0
        sr = hypot(tx, ty)
        if sr > 5.0:
            tx = tx / sr * 5.0
            ty = ty / sr * 5.0
        elif er > 5.5 and sr > 4.2:
            tx = tx * 0.7
            ty = ty * 0.7

    b = bearing_to(tx, ty)
    d = distance_to(tx, ty)

    if de < 2.2 and mr < 4.5:
        if 'orbit' not in me.memory:
            me.memory['orbit'] = 1
        if arena.time - me.memory.get('ot', 0.0) > 4.0:
            me.memory['orbit'] = -me.memory['orbit']
            me.memory['ot'] = arena.time
        b = b + 30.0 * me.memory['orbit']
        if b > 180.0:
            b = b - 360.0
        if b < -180.0:
            b = b + 360.0

    base = 1.0
    if d < 0.3:
        base = 0.4
    elif d < 0.8:
        base = 0.7
    elif d < 2.0:
        base = 0.9

    if abs(b) > 60.0:
        base = 0.4
    if mr > 4.8 and base > 0.8:
        base = 0.8

    turn = b / 18.0
    if turn > 1.0:
        turn = 1.0
    if turn < -1.0:
        turn = -1.0

    left = base - 0.8 * turn
    right = base + 0.8 * turn

    if left < -1.0:
        left = -1.0
    if left > 1.0:
        left = 1.0
    if right < -1.0:
        right = -1.0
    if right > 1.0:
        right = 1.0

    return (left, right)


